import json
ITEMS=[]
def base(i,cap,fmt,b,prompt,step,rat,a):
    return {"kind":"code","id":i,"version":1,"target":cap,"format":fmt,"b":b,"a":a,"prompt":prompt,"step":step,"rationale":rat,"difficulty_source":"expert_estimate","review":"draft-unreviewed","evidence_status":"provisional"}
def ch(i,cap,fmt,b,prompt,opts,ans,step,rat,tags=None,addr=None):
    it=base(i,cap,fmt,b,prompt,step,rat,1.1); it["options"]=opts; it["answer"]=ans
    if tags: it["distractor_tags"]={str(k):v for k,v in tags.items()}
    if addr: it["addresses"]=addr
    ITEMS.append(it)
def ty(i,cap,fmt,b,prompt,answers,step,rat,wrong=None,addr=None):
    it=base(i,cap,fmt,b,prompt,step,rat,1.3); it["answers"]=answers
    if wrong: it["wrong"]=wrong
    if addr: it["addresses"]=addr
    ITEMS.append(it)
def mu(i,cap,fmt,b,prompt,opts,aset,step,rat):
    it=base(i,cap,fmt,b,prompt,step,rat,1.1); it["options"]=opts; it["answer_set"]=aset; ITEMS.append(it)
def od(i,cap,fmt,b,prompt,opts,order,step,rat):
    it=base(i,cap,fmt,b,prompt,step,rat,1.2); it["options"]=opts; it["answer_order"]=order; ITEMS.append(it)

