# keyed answers never carry a distractor tag: a tag on the keyed (erroneous) sentence moves to "addresses"
for it in ITEMS:
    t=it.get("distractor_tags")
    if t and str(it.get("answer")) in t:
        tag=t.pop(str(it["answer"])); it["addresses"]=sorted(set(it.get("addresses",[]))|{tag})
        if not t: it.pop("distractor_tags")
# balance keyed positions in choice questions (deterministic): rotate options so the key lands at k mod n
NO_SHUFFLE={"sup.g8.fra.07"}  # options are letters of the prompt
k_by_cap={}
for it in ITEMS:
    if not it["format"].startswith("choice") or it["id"] in NO_SHUFFLE: continue
    n=len(it["options"]); k=k_by_cap.get(it["target"],0); k_by_cap[it["target"]]=k+1
    want=(k*3+1)%n
    shift=(want-it["answer"])%n
    newpos=lambda i:(i+shift)%n
    opts=[None]*n
    for i,o in enumerate(it["options"]): opts[newpos(i)]=o
    it["options"]=opts; it["answer"]=newpos(it["answer"])
    if "distractor_tags" in it: it["distractor_tags"]={str(newpos(int(k2))):v for k2,v in it["distractor_tags"].items()}

import collections
print(len(ITEMS), collections.Counter(i["target"] for i in ITEMS))
assert len({i["id"] for i in ITEMS})==len(ITEMS)
json.dump(ITEMS, open("content/english/proposed/g8-supplement-v1/items.json","w"), indent=1, ensure_ascii=False)
